using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.SceneManagement;using Staff.Shared;using Staff.Characters;using Staff.Subway;
namespace Staff.Traversal.Editor {
[InitializeOnLoad] public static class ScenePolishReview {
 const string W="Library/TangentMath/";
 static ScenePolishReview(){EditorApplication.update+=Poll;}
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);File.AppendAllText(W+"polish.txt","PASS "+label+"\n");}
 static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||!File.Exists(W+"polish.request"))return;File.Delete(W+"polish.request");File.WriteAllText(W+"polish.txt","");try{Run();}catch(Exception e){File.AppendAllText(W+"polish.txt",e.ToString());}}
 static void Run(){var go=new GameObject("Temporary defaults review");go.SetActive(false);var cam=go.AddComponent<Camera>();cam.pixelRect=new Rect(0,0,1920,1080);try{Check(!go.AddComponent<AdventureMotionVersion>().UseGenshin,"Unity Starter default");Check(!go.AddComponent<CharacterSwitcher>().PhysicsEnabled,"P off default");Check(Mathf.Approximately(TangentEquationUI.DisplaySize(cam,new Vector3(0,0,10000)).y,30),"far minimum 30");Check(Mathf.Approximately(TangentEquationUI.DisplaySize(cam,new Vector3(0,0,.1f)).y,60),"near maximum 60");}finally{UnityEngine.Object.DestroyImmediate(go);}
 foreach(var scene in EditorBuildSettings.scenes.Where(s=>s.enabled))Check(Resources.Load<Texture2D>("SceneThumbnails/"+Path.GetFileNameWithoutExtension(scene.path)),"thumbnail "+scene.path);
 var rig=UnityEngine.Object.FindFirstObjectByType<SharedGameplay>();if(rig){var mode=rig.cameraController.GetComponent<AbstractEnvironment>();var old=mode.Mode;try{mode.SetMode(AbstractEnvironment.EnvironmentMode.Imaginary);Check(TangentTraversal.InkColor(mode.GetComponent<Camera>())==Color.black,"Imaginary tangent ink");var env=mode.EnvironmentRenderers.ToArray();var trains=rig.gameObject.scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<SubwayConsist>(true)).ToArray();foreach(var train in trains){var renderers=train.GetComponentsInChildren<Renderer>(true);Check(renderers.Length>0&&renderers.All(env.Contains),"all train renderers in environment: "+renderers.Length);Check(renderers.Any(r=>(r.hideFlags&HideFlags.DontSave)!=0||(r.gameObject.hideFlags&HideFlags.DontSave)!=0),"generated DontSave geometry covered");}}finally{mode.SetMode(old);}}
 if(Application.isPlaying){var picker=UnityEngine.Object.FindFirstObjectByType<ScenePicker>();if(!picker){typeof(ScenePicker).GetMethod("Install",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,null);picker=UnityEngine.Object.FindFirstObjectByType<ScenePicker>();}Check(picker,"scene picker installed");var flags=BindingFlags.NonPublic|BindingFlags.Instance;var player=UnityEngine.Object.FindFirstObjectByType<AdventurePlayer>();bool blocked=player&&player.InputBlocked;typeof(ScenePicker).GetMethod("Open",flags).Invoke(picker,null);Check((bool)typeof(ScenePicker).GetField("open",flags).GetValue(picker),"scene list opens");if(player)Check(player.InputBlocked,"scene list blocks gameplay");typeof(ScenePicker).GetMethod("Close",flags).Invoke(picker,null);Check(!(bool)typeof(ScenePicker).GetField("open",flags).GetValue(picker),"scene list closes");if(player)Check(player.InputBlocked==blocked,"scene list restores input");}
 }
}
}
